void init_pi_mutex(pthread_mutex_t* m) {
  pthread_mutexattr_t ma;
  pthread_mutexattr_init(&ma);
  pthread_mutexattr_setprotocol(&ma, PTHREAD_PRIO_INHERIT);
  pthread_mutex_init(m, &ma);
  pthread_mutexattr_destroy(&ma);
}

int start_rt_thread(pthread_t* t, void* (*fn)(void*), void* arg, int prio) {
  pthread_attr_t a;
  pthread_attr_init(&a);
  // Without this the policy below is ignored (default is INHERIT_SCHED).
  pthread_attr_setinheritsched(&a, PTHREAD_EXPLICIT_SCHED);
  pthread_attr_setschedpolicy(&a, SCHED_FIFO);
  sched_param sp{};
  sp.sched_priority = prio;  // 1..99
  pthread_attr_setschedparam(&a, &sp);
  int rc = pthread_create(t, &a, fn, arg);  // EPERM without CAP_SYS_NICE / RLIMIT_RTPRIO
  pthread_attr_destroy(&a);
  return rc;
}
